PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, school_id TEXT NOT NULL, role TEXT NOT NULL, password_hash TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY, school_id TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS contests(id TEXT PRIMARY KEY, school_id TEXT NOT NULL, published_version_id TEXT, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX IF NOT EXISTS contests_school ON contests(school_id);
CREATE TABLE IF NOT EXISTS versions(id TEXT PRIMARY KEY, contest_id TEXT NOT NULL REFERENCES contests(id), etag TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX IF NOT EXISTS versions_contest_status ON versions(contest_id,status);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY, contest_id TEXT NOT NULL REFERENCES contests(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS publicity(id TEXT PRIMARY KEY, contest_id TEXT NOT NULL REFERENCES contests(id), etag TEXT NOT NULL, status TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, contest_id TEXT NOT NULL REFERENCES contests(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS favorites(user_id TEXT NOT NULL REFERENCES users(id), contest_id TEXT NOT NULL REFERENCES contests(id), data TEXT NOT NULL CHECK(json_valid(data)), PRIMARY KEY(user_id,contest_id));
CREATE TABLE IF NOT EXISTS feedback(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE INDEX IF NOT EXISTS feedback_user ON feedback(user_id);
CREATE TABLE IF NOT EXISTS publicity_actions(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS draft_fields(version_id TEXT PRIMARY KEY REFERENCES versions(id), data TEXT NOT NULL CHECK(json_valid(data)));
CREATE TABLE IF NOT EXISTS withdrawn_types(key TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
INSERT OR IGNORE INTO schema_migrations VALUES(1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
